  const mainOffset = collapsed ? (isArabic ? "md:pr-[78px] md:pl-0" : "md:pl-[78px] md:pr-0") : (isArabic ? "md:pr-[248px] md:pl-0" : "md:pl-[248px] md:pr-0");
